import { readdir, readFile, access } from 'node:fs/promises';
import { join, dirname, resolve } from 'node:path';
const OUT = 'public';
async function walk(d){ const out=[]; for(const e of await readdir(d,{withFileTypes:true})){ const p=join(d,e.name); if(e.isDirectory()) out.push(...await walk(p)); else out.push(p);} return out; }
const files = (await walk(OUT)).filter(f=>f.endsWith('.html'));
let bad=0, checked=0;
for(const f of files){
  const html = await readFile(f,'utf8');
  for(const m of html.matchAll(/(?:href|src)="([^"]+)"/g)){
    const h=m[1];
    if(/^(https?:|mailto:|#)/.test(h)) continue;
    checked++;
    const clean=h.split('#')[0];
    let target = clean.startsWith('/') ? join(OUT,clean) : resolve(dirname(f), clean);
    try{ await access(target); }
    catch{
      // directory-style URL -> index.html
      try{ await access(join(target,'index.html')); }
      catch{ console.log(`BROKEN ${f} -> ${h}`); bad++; }
    }
  }
}
console.log(`checked ${checked} internal refs across ${files.length} pages, broken=${bad}`);
process.exit(bad?1:0);
EOF
node /tmp/linkcheck.mjs

